import { chromium } from "playwright-core";
const out = "/workspace/hermes-mobile/dist/screens";
const b = await chromium.launch({ executablePath: "/opt/google/chrome/chrome", args: ["--no-sandbox"] });
const p = await (await b.newContext({ viewport: { width: 412, height: 915 }, deviceScaleFactor: 2 })).newPage();
const errs = []; p.on("pageerror", (e) => errs.push(String(e)));
await p.goto("http://localhost:8799/"); await p.waitForTimeout(2500);
console.log("first screen has Connect:", await p.getByText("Connect to Hermes").count());
await p.screenshot({ path: `${out}/16-live-settings.png` });
const fill = async (l, v) => p.getByLabel(l, { exact: true }).filter({ visible: true }).first().fill(v);
await fill("Server URL", "hermes.does-not-exist.invalid/");
await fill("Hermes API key", "bogus-key");
await fill("Cloudflare Access Client ID", "x.access");
await fill("Cloudflare Access Client Secret", "y");
await p.getByText("Test & save").click(); await p.waitForTimeout(4000);
const msg = await p.locator("text=/Can't reach|refused|Reached|Fill in|https/").allInnerTexts();
console.log("error shown:", msg.slice(-1));
console.log("url normalized:", await p.getByLabel("Server URL", { exact: true }).filter({ visible: true }).first().inputValue());
await p.screenshot({ path: `${out}/16-live-test-failed.png` });
await p.getByText("Save anyway (test later)").click(); await p.waitForTimeout(5000);
await p.screenshot({ path: `${out}/16-live-offline.png` });
console.log("body:", (await p.locator("body").innerText()).replace(/\s+/g, " ").slice(0, 300));
console.log("storage:", await p.evaluate(() => Object.keys(localStorage).filter(k => k.startsWith("hermes.")).join(",")));
console.log("pageerrors:", errs.length, errs.slice(0, 3));
await b.close();
